package tokenizer

import java.time.format.DateTimeFormatter
import java.time.{LocalDate, LocalDateTime}
import java.util.Locale

import io.circe.{Json, ParsingFailure}
import io.circe.parser.parse
import scala.collection.mutable
import scala.math.BigDecimal.RoundingMode

/**
 * Tokenizer module for converting various input types to standardized string tokens.
 *
 * This is the Scala counterpart of a Python data-preparation module. Python's
 * duck typing, union types, and optional values are translated into the
 * constructs a Scala developer would reach for:
 *
 *  - Protocol classes (structural typing)  -> type classes (`Tokenizable`, `HasLength`)
 *  - union types (`str | bytes`, numeric unions, `Any` dispatch) -> sealed traits / ADTs
 *  - `Optional` / `None`                   -> `Option`, `Either`
 *  - `isinstance` dispatch                 -> pattern matching on an ADT
 *  - mutable default arguments             -> immutable defaults (a Scala strength)
 */

// ============================================================================
// Type classes (Scala's answer to Python's Protocol / structural typing)
// ============================================================================

/**
 * Type class for any value that can be rendered as a token string.
 *
 * The Python original is a `Protocol` checked at runtime with `isinstance`;
 * in Scala the same capability is provided by implicit evidence, which is
 * resolved at compile time.
 */
trait Tokenizable[A] {
  def toToken(value: A): String
}

object Tokenizable {

  def apply[A](implicit instance: Tokenizable[A]): Tokenizable[A] = instance

  /** Extension syntax so that `value.toToken` reads the same as `value.to_token()`. */
  implicit final class TokenizableOps[A](private val value: A) extends AnyVal {
    def toToken(implicit instance: Tokenizable[A]): String = instance.toToken(value)
  }

  // Built-in instances.
  implicit val stringTokenizable: Tokenizable[String] = (value: String) => value
  implicit val intTokenizable: Tokenizable[Int] = (value: Int) => value.toString
  implicit val doubleTokenizable: Tokenizable[Double] = (value: Double) => value.toString
  implicit val booleanTokenizable: Tokenizable[Boolean] = (value: Boolean) => value.toString
}

/** Type class for any value that exposes a length (Python's `HasLength` protocol). */
trait HasLength[A] {
  def length(value: A): Int
}

object HasLength {
  implicit val stringHasLength: HasLength[String] = (value: String) => value.length
  implicit def seqHasLength[A]: HasLength[Seq[A]] = (value: Seq[A]) => value.length
}

/** Contravariant processor that consumes items (Python's `TokenProcessor` protocol). */
trait TokenProcessor[-A] {
  def process(item: A): Unit
}

// ============================================================================
// Enums and constants
// ============================================================================

/** Enumeration of token categories. */
sealed abstract class TokenType(val value: String) extends Product with Serializable

object TokenType {
  case object STRING extends TokenType("string")
  case object NUMERIC extends TokenType("numeric")
  case object TEMPORAL extends TokenType("temporal")
  case object STRUCTURED extends TokenType("structured")
  case object BINARY extends TokenType("binary")
  case object NULL extends TokenType("null")

  val values: Seq[TokenType] = Seq(STRING, NUMERIC, TEMPORAL, STRUCTURED, BINARY, NULL)

  /** Looks up a token type by its string value. */
  def fromString(value: String): Option[TokenType] = values.find(_.value == value)
}

// ============================================================================
// Core token classes
// ============================================================================

/**
 * Immutable token representation.
 *
 * Like Python's `frozen=True` dataclass, a `Token` is a value: equality is
 * structural and no field can be reassigned.
 */
final case class Token(
    value: String,
    tokenType: TokenType,
    metadata: Map[String, Any] = Map.empty
) {

  /** Returns a copy of this token merged with additional metadata entries. */
  def withMetadata(entries: (String, Any)*): Token =
    copy(metadata = metadata ++ entries)
}

/**
 * Mutable batch of tokens, in deliberate contrast with the immutable `Token`.
 *
 * Adding a token after the batch has been processed is a state violation and
 * raises `IllegalStateException`.
 */
final class MutableTokenBatch {

  private val buffer = mutable.ListBuffer.empty[Token]
  private var processed = false

  def add(token: Token): Unit = {
    if (processed)
      throw new IllegalStateException("Batch already processed")
    buffer += token
  }

  def markProcessed: Unit = processed = true

  def isProcessed: Boolean = processed

  def tokens: List[Token] = buffer.toList
}

// ============================================================================
// Generic container classes
// ============================================================================

/**
 * Covariant, immutable container: `TokenContainer[String]` can be used wherever
 * a `TokenContainer[Any]` is expected (Python's `Generic[T_co]`).
 */
final class TokenContainer[+A](items: Seq[A]) {

  private val values: Vector[A] = items.toVector

  def getAll: Vector[A] = values

  def size: Int = values.size

  /** Maps every item with `f`, returning the results as a vector. */
  def mapTokens[B](f: A => B): Vector[B] = values.map(f)
}

/**
 * Contravariant sink: a `TokenSink[Any]` can be used wherever a
 * `TokenSink[String]` is expected (Python's `Generic[T_contra]`).
 */
final class TokenSink[-A] {

  private val received = mutable.ListBuffer.empty[Any]

  def receive(item: A): Unit = received += item

  /** Returns all received items and clears the sink. */
  def drain: List[Any] = {
    val result = received.toList
    received.clear()
    result
  }
}

/** Invariant holder with get/set/transform (Python's `BivariantHandler`). */
final class BivariantHandler[A](private var value: A) {

  def get: A = value

  def set(newValue: A): Unit = value = newValue

  /** Applies `f` to the held value, updates the holder, and returns the result. */
  def transform(f: A => A): A = {
    value = f(value)
    value
  }
}

// ============================================================================
// Union types: str | bytes, numeric values, and date/time values
// ============================================================================

/** Models Python's `str | bytes` union. */
sealed trait StrOrBytes {
  def asString(encoding: String): String
}

object StrOrBytes {
  final case class Str(value: String) extends StrOrBytes {
    def asString(encoding: String): String = value
  }

  final case class Bytes(value: Array[Byte]) extends StrOrBytes {
    def asString(encoding: String): String = new String(value, encoding)
  }

  implicit def fromString(value: String): StrOrBytes = Str(value)
  implicit def fromBytes(value: Array[Byte]): StrOrBytes = Bytes(value)
}

/**
 * Models Python's numeric union (`int | float | Decimal`).
 * Scala's `BigDecimal` plays the role of Python's `Decimal`.
 */
sealed trait NumericValue {
  def typeName: String
}

object NumericValue {
  final case class IntValue(value: Int) extends NumericValue { val typeName = "Int" }
  final case class LongValue(value: Long) extends NumericValue { val typeName = "Long" }
  final case class FloatValue(value: Float) extends NumericValue { val typeName = "Float" }
  final case class DoubleValue(value: Double) extends NumericValue { val typeName = "Double" }
  final case class BigDecimalValue(value: BigDecimal) extends NumericValue {
    val typeName = "BigDecimal"
  }

  implicit def fromInt(value: Int): NumericValue = IntValue(value)
  implicit def fromLong(value: Long): NumericValue = LongValue(value)
  implicit def fromFloat(value: Float): NumericValue = FloatValue(value)
  implicit def fromDouble(value: Double): NumericValue = DoubleValue(value)
  implicit def fromBigDecimal(value: BigDecimal): NumericValue = BigDecimalValue(value)
}

/** Models Python's `datetime | date` union (backed by `java.time`). */
sealed trait TemporalValue

object TemporalValue {
  final case class DateTime(value: LocalDateTime) extends TemporalValue
  final case class Date(value: LocalDate) extends TemporalValue

  implicit def fromLocalDateTime(value: LocalDateTime): TemporalValue = DateTime(value)
  implicit def fromLocalDate(value: LocalDate): TemporalValue = Date(value)
}

// ============================================================================
// Tokenizer implementations
// ============================================================================

/** Abstract base tokenizer for a single input type `A`. */
abstract class BaseTokenizer[A] {

  /** Converts one value to a token. */
  def tokenize(value: A): Token

  /** Lazily tokenizes a stream of values. */
  def tokenizeBatch(values: Iterable[A]): Iterator[Token] =
    values.iterator.map(tokenize)
}

/** Tokenizer for strings and byte arrays. */
final class StringTokenizer(
    val encoding: String = "UTF-8",
    val normalizer: String => String = identity
) extends BaseTokenizer[StrOrBytes] {

  def tokenize(value: StrOrBytes): Token =
    Token(normalizer(value.asString(encoding)), TokenType.STRING)

  def tokenizeString(value: String): Token =
    tokenize(StrOrBytes.Str(value))

  def tokenizeBytes(value: Array[Byte]): Token =
    tokenize(StrOrBytes.Bytes(value))
}

/**
 * Tokenizer for numeric values with precision handling.
 *
 * Python's mutable default argument (`format_options={}`) is impossible in
 * Scala: the default here is the immutable, shared `Map.empty`.
 */
final class NumericTokenizer(
    val precision: Int = 6,
    val formatOptions: Map[String, Any] = Map.empty
) extends BaseTokenizer[NumericValue] {

  private val decimalFormat = s"%.${precision}f"

  def tokenize(value: NumericValue): Token =
    value match {
      case NumericValue.BigDecimalValue(decimal) =>
        Token(decimal.setScale(precision, RoundingMode.HALF_UP).toPlainString,
              TokenType.NUMERIC,
              Map("original_type" -> "BigDecimal"))
      case NumericValue.DoubleValue(double) =>
        Token(java.lang.String.format(Locale.ROOT, decimalFormat, double),
              TokenType.NUMERIC,
              Map("original_type" -> "Double"))
      case NumericValue.FloatValue(float) =>
        Token(java.lang.String.format(Locale.ROOT, decimalFormat, float),
              TokenType.NUMERIC,
              Map("original_type" -> "Float"))
      case NumericValue.IntValue(int) =>
        Token(int.toString, TokenType.NUMERIC, Map("original_type" -> "Int"))
      case NumericValue.LongValue(long) =>
        Token(long.toString, TokenType.NUMERIC, Map("original_type" -> "Long"))
    }

  def tokenizeInt(value: Int): Token = tokenize(NumericValue.IntValue(value))
  def tokenizeLong(value: Long): Token = tokenize(NumericValue.LongValue(value))
  def tokenizeFloat(value: Float): Token = tokenize(NumericValue.FloatValue(value))
  def tokenizeDouble(value: Double): Token = tokenize(NumericValue.DoubleValue(value))
  def tokenizeBigDecimal(value: BigDecimal): Token =
    tokenize(NumericValue.BigDecimalValue(value))
}

/** Tokenizer for date and date/time values. */
final class TemporalTokenizer(val formatStr: Option[String] = None)
    extends BaseTokenizer[TemporalValue] {

  private val isoDateTime = DateTimeFormatter.ofPattern("yyyy-MM-dd'T'HH:mm:ss")
  private val isoDate = DateTimeFormatter.ofPattern("yyyy-MM-dd")

  private def formatterFor(value: TemporalValue): DateTimeFormatter =
    formatStr match {
      case Some(pattern) => DateTimeFormatter.ofPattern(pattern)
      case None =>
        value match {
          case TemporalValue.DateTime(_) => isoDateTime
          case TemporalValue.Date(_) => isoDate
        }
    }

  def tokenize(value: TemporalValue): Token = {
    val temporal = value match {
      case TemporalValue.DateTime(dateTime) => dateTime
      case TemporalValue.Date(date) => date
    }
    Token(formatterFor(value).format(temporal), TokenType.TEMPORAL)
  }

  def tokenizeDateTime(value: LocalDateTime): Token =
    tokenize(TemporalValue.DateTime(value))

  def tokenizeDate(value: LocalDate): Token =
    tokenize(TemporalValue.Date(value))
}

// ============================================================================
// Universal tokenizer: Any-style dispatch over a sealed value ADT
// ============================================================================

/**
 * Models the heterogeneous input of Python's `UniversalTokenizer.tokenize(value: Any)`.
 *
 * Python decides at runtime with `isinstance`; Scala models the same
 * "some value of one of these shapes" as an ADT, and dispatch is exhaustive
 * pattern matching. `CustomVal` carries the type-class evidence that a
 * Python object would have provided by duck typing.
 */
sealed trait TokenizableValue

object TokenizableValue {
  case object NullVal extends TokenizableValue
  final case class StringVal(value: String) extends TokenizableValue
  final case class BytesVal(value: Array[Byte]) extends TokenizableValue
  final case class IntVal(value: Int) extends TokenizableValue
  final case class LongVal(value: Long) extends TokenizableValue
  final case class FloatVal(value: Float) extends TokenizableValue
  final case class DoubleVal(value: Double) extends TokenizableValue
  final case class BigDecimalVal(value: BigDecimal) extends TokenizableValue
  final case class DateTimeVal(value: LocalDateTime) extends TokenizableValue
  final case class DateVal(value: LocalDate) extends TokenizableValue

  /** Any value with a `Tokenizable` instance in scope (the duck-typed case). */
  final case class CustomVal[A](value: A)(implicit tokenizable: Tokenizable[A])
      extends TokenizableValue {
    def toToken: String = tokenizable.toToken(value)
  }

  // Implicit conversions mirror Python's ability to pass raw values anywhere.
  implicit def fromString(value: String): TokenizableValue = StringVal(value)
  implicit def fromBytes(value: Array[Byte]): TokenizableValue = BytesVal(value)
  implicit def fromInt(value: Int): TokenizableValue = IntVal(value)
  implicit def fromLong(value: Long): TokenizableValue = LongVal(value)
  implicit def fromFloat(value: Float): TokenizableValue = FloatVal(value)
  implicit def fromDouble(value: Double): TokenizableValue = DoubleVal(value)
  implicit def fromBigDecimal(value: BigDecimal): TokenizableValue = BigDecimalVal(value)
  implicit def fromLocalDateTime(value: LocalDateTime): TokenizableValue =
    DateTimeVal(value)
  implicit def fromLocalDate(value: LocalDate): TokenizableValue = DateVal(value)
}

/**
 * Tokenizer that dispatches to the specialized tokenizer matching the value's
 * shape, with a string fallback for anything else.
 */
final class UniversalTokenizer {

  private val stringTokenizer = new StringTokenizer()
  private val numericTokenizer = new NumericTokenizer()
  private val temporalTokenizer = new TemporalTokenizer()

  /** Token for Python's `None` / Scala's `null`. */
  def tokenizeNull: Token = Token("NULL", TokenType.NULL)

  def tokenize(value: TokenizableValue): Token =
    value match {
      case TokenizableValue.NullVal => tokenizeNull
      case TokenizableValue.CustomVal(custom) =>
        Token(custom.toToken, TokenType.STRUCTURED)
      case TokenizableValue.StringVal(text) => stringTokenizer.tokenizeString(text)
      case TokenizableValue.BytesVal(bytes) => stringTokenizer.tokenizeBytes(bytes)
      case TokenizableValue.IntVal(int) => numericTokenizer.tokenizeInt(int)
      case TokenizableValue.LongVal(long) => numericTokenizer.tokenizeLong(long)
      case TokenizableValue.FloatVal(float) => numericTokenizer.tokenizeFloat(float)
      case TokenizableValue.DoubleVal(double) => numericTokenizer.tokenizeDouble(double)
      case TokenizableValue.BigDecimalVal(decimal) =>
        numericTokenizer.tokenizeBigDecimal(decimal)
      case TokenizableValue.DateTimeVal(dateTime) => temporalTokenizer.tokenizeDateTime(dateTime)
      case TokenizableValue.DateVal(date) => temporalTokenizer.tokenizeDate(date)
    }

  // Ergonomic overloads for the most common input types.
  def tokenize(value: String): Token = tokenize(TokenizableValue.StringVal(value))
  def tokenize(value: Array[Byte]): Token = tokenize(TokenizableValue.BytesVal(value))
  def tokenize(value: Int): Token = tokenize(TokenizableValue.IntVal(value))
  def tokenize(value: Long): Token = tokenize(TokenizableValue.LongVal(value))
  def tokenize(value: Float): Token = tokenize(TokenizableValue.FloatVal(value))
  def tokenize(value: Double): Token = tokenize(TokenizableValue.DoubleVal(value))
  def tokenize(value: BigDecimal): Token = tokenize(TokenizableValue.BigDecimalVal(value))
  def tokenize(value: LocalDateTime): Token =
    tokenize(TokenizableValue.DateTimeVal(value))
  def tokenize(value: LocalDate): Token = tokenize(TokenizableValue.DateVal(value))

  /**
   * Fallback for values that do not fit the ADT above, mirroring Python's
   * `str(value)` branch.
   */
  def tokenizeAny(value: Any): Token =
    value match {
      case null => tokenizeNull
      case string: String => tokenize(string)
      case bytes: Array[Byte] => tokenize(bytes)
      case decimal: BigDecimal => numericTokenizer.tokenizeBigDecimal(decimal)
      case number: java.lang.Number =>
        Token(number.toString,
              TokenType.NUMERIC,
              Map("original_type" -> number.getClass.getSimpleName))
      case dateTime: LocalDateTime => tokenize(dateTime)
      case date: LocalDate => tokenize(date)
      case other => Token(other.toString, TokenType.STRING, Map("fallback" -> true))
    }
}

// ============================================================================
// Registry with nested generics
// ============================================================================

/**
 * Registry mapping keys to token containers, plus a chain of handlers.
 *
 * Processing a key runs every item of the registered container through the
 * handlers and keeps the result of the first handler that yields a token.
 */
final class TokenRegistry[A] {

  private val containers = mutable.Map.empty[String, TokenContainer[A]]
  private val handlers = mutable.ListBuffer.empty[A => Option[Token]]

  def register(key: String, container: TokenContainer[A]): Unit =
    containers.update(key, container)

  def addHandler(handler: A => Option[Token]): Unit =
    handlers += handler

  def container(key: String): Option[TokenContainer[A]] = containers.get(key)

  /**
   * Processes all items of the container registered under `key`.
   * Returns `Nil` if no container is registered; an item for which no handler
   * produces a token contributes a `None`.
   */
  def process(key: String): List[Option[Token]] =
    containers
      .get(key)
      .map { container =>
        container.getAll.iterator
          .map { item =>
            handlers.iterator.map(_(item)).collectFirst { case Some(token) => token }
          }
          .toList
      }
      .getOrElse(Nil)
}

// ============================================================================
// Functor and monad wrappers
// ============================================================================

/**
 * Wraps a value with mapping operations, as in the Python `TokenFunctor`.
 *
 * Python could not express the result types precisely; here `map` keeps the
 * wrapped type, which the value of `B` in `TokenFunctor[B]` records.
 */
class TokenFunctor[A](private val value: A) {

  def map[B](f: A => B): TokenFunctor[B] = new TokenFunctor(f(value))

  def flatMap[B](f: A => TokenFunctor[B]): TokenFunctor[B] = f(value)

  /** The wrapped value, or `default` when the wrapped value is `null`. */
  def getOrElse(default: => A): A =
    if (value == null) default else value

  def get: A = value

  def toOption: Option[A] = Option(value)
}

/** `TokenFunctor` extended with the monadic/applicative operations of Python's `TokenMonad`. */
final class TokenMonad[A](value: A) extends TokenFunctor[A](value) {

  override def map[B](f: A => B): TokenMonad[B] = new TokenMonad(f(get))

  override def flatMap[B](f: A => TokenFunctor[B]): TokenMonad[B] =
    new TokenMonad(f(get).get)

  /** Applicative apply: lifts `funcWrapped` over this monad's value. */
  def ap[B](funcWrapped: TokenMonad[A => B]): TokenMonad[B] =
    new TokenMonad(funcWrapped.get(get))
}

object TokenMonad {
  def pure[A](value: A): TokenMonad[A] = new TokenMonad(value)
}

// ============================================================================
// JSON structure tokenization (recursive JSON value via Circe's Json ADT)
// ============================================================================

/**
 * Tokenizer for JSON structures.
 *
 * Python's recursive union `JsonValue = str | int | float | bool | None |
 * list[JsonValue] | dict[str, JsonValue]` becomes simply Circe's `Json`,
 * which is itself a recursive algebraic data type.
 */
final class JsonTokenizer(val pretty: Boolean = false) {

  def tokenize(value: Json): Token =
    Token(
      if (pretty) value.spaces2 else value.noSpaces,
      TokenType.STRUCTURED,
      Map("json" -> true)
    )

  /** Parses a JSON document and tokenizes it; `Left` carries the parse error. */
  def tokenizeString(json: String): Either[ParsingFailure, Token] =
    parse(json).map(tokenize)

  /**
   * Extracts and tokenizes the value at a dotted path such as `user.name` or
   * `items.1`. Returns `None` when the path cannot be resolved.
   */
  def tokenizePath(value: Json, path: String): Option[Token] =
    navigate(value, path.split("\\.").toList).map(tokenize)

  private def navigate(value: Json, parts: List[String]): Option[Json] =
    parts match {
      case Nil => Some(value)
      case part :: rest => lookup(value, part).flatMap(navigate(_, rest))
    }

  private def lookup(value: Json, part: String): Option[Json] =
    if (value.isObject) value.hcursor.downField(part).focus
    else if (part.forall(_.isDigit)) value.asArray.flatMap(_.lift(part.toInt))
    else None
}

// ============================================================================
// Whitespace tokenizer
// ============================================================================

/**
 * Splits text on runs of whitespace and normalizes each word into a token.
 *
 * Options mirror the Python implementation: optional lowercasing, minimum
 * length filtering, maximum length truncation, and punctuation stripping.
 */
final class WhitespaceTokenizer(
    val lowercase: Boolean = false,
    val minLength: Int = 0,
    val maxLength: Option[Int] = None,
    val stripPunctuation: Boolean = false
) {

  private val punctuation: Set[Char] =
    Set('.', ',', '!', '?', ';', ':', '\'', '"', '(', ')', '[', ']', '{', '}')

  private def stripSurroundingPunctuation(word: String): String =
    word.reverse.dropWhile(punctuation.contains).reverse.dropWhile(punctuation.contains).reverse

  /** Applies all options to one word; `None` means the word is dropped. */
  private def processToken(word: String): Option[String] = {
    val base = if (stripPunctuation) stripSurroundingPunctuation(word) else word
    val lowered = if (lowercase) base.toLowerCase else base
    if (lowered.length < minLength) None
    else
      maxLength match {
        case Some(max) if lowered.length > max => Some(lowered.take(max))
        case _ => if (lowered.isEmpty) None else Some(lowered)
      }
  }

  private def words(text: String): List[String] =
    text.split("\\s+").toList.filter(_.nonEmpty)

  /**
   * Splits text on whitespace and returns one token per surviving word,
   * with the word's index and original form recorded in the metadata.
   */
  def tokenize(text: String): List[Token] =
    words(text).zipWithIndex.flatMap {
      case (word, position) =>
        processToken(word).map { tokenText =>
          Token(tokenText,
                TokenType.STRING,
                Map("position" -> position, "original" -> word))
        }
    }

  /** Convenience variant returning only the token strings. */
  def tokenizeToStrings(text: String): List[String] =
    tokenize(text).map(_.value)

  /**
   * Tokenizes text and returns `(token, start, end)` triples with character
   * offsets into the original text.
   */
  def tokenizeWithPositions(text: String): List[(String, Int, Int)] = {
    def loop(words: List[String], from: Int, acc: List[(String, Int, Int)]):
        List[(String, Int, Int)] =
      words match {
        case Nil => acc.reverse
        case word :: rest =>
          val start = text.indexOf(word, from)
          val end = start + word.length
          val updated =
            processToken(word) match {
              case Some(tokenText) => (tokenText, start, end) :: acc
              case None => acc
            }
          loop(rest, end, updated)
      }
    loop(words(text), 0, Nil)
  }

  /** The number of tokens the text would produce. */
  def countTokens(text: String): Int =
    tokenize(text).size
}

// ============================================================================
// Builder pattern with a fluent interface
// ============================================================================

/**
 * Immutable, fluent builder for custom tokenizers.
 *
 * Every `with*` method returns an updated copy instead of mutating shared
 * state (the Python original mutates and returns `self`).
 */
final class TokenizerBuilder[A] private (
    private val normalizers: Vector[String => String],
    private val validators: Vector[A => Boolean],
    private val metadata: Map[String, Any]
) {

  def withNormalizer(normalizer: String => String): TokenizerBuilder[A] =
    new TokenizerBuilder(normalizers :+ normalizer, validators, metadata)

  def withValidator(validator: A => Boolean): TokenizerBuilder[A] =
    new TokenizerBuilder(normalizers, validators :+ validator, metadata)

  def withMetadata(entries: (String, Any)*): TokenizerBuilder[A] =
    new TokenizerBuilder(normalizers, validators, metadata ++ entries)

  /**
   * Builds the tokenizer function. At tokenization time the value is first
   * validated (failure raises `IllegalArgumentException`), then stringified,
   * and finally passed through the normalizers in order.
   */
  def build: A => Token = {
    value =>
      val invalid = validators.exists(!_(value))
      if (invalid)
        throw new IllegalArgumentException(s"Validation failed for $value")
      val normalized = normalizers.foldLeft(value.toString) { (text, normalizer) =>
        normalizer(text)
      }
      Token(normalized, TokenType.STRING, metadata)
  }
}

object TokenizerBuilder {
  def apply[A](): TokenizerBuilder[A] =
    new TokenizerBuilder(Vector.empty, Vector.empty, Map.empty)
}
